


export type TippingSettings = { "default_enabled"?: boolean; /** The preselected fixed tip. Its amount and currency must match one of the effective smart_tip_money_options. Null means no preselection is set at this scope; effective settings may inherit a preselection from a parent scope. */ "default_smart_tip_money": ((({ /** Use an exact numeric string, not a floating-point number. Format: int64. minimum: 1. */ "amount"?: string; }) & ({ /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; })) | (null) | (unknown)); /** The preselected percentage, from 1 through 100. It must match one of the effective tip_percentages. Null means no preselection is set at this scope; effective settings may inherit a preselection from a parent scope. minimum: 1. maximum: 100. */ "default_tip_percentage": number | null; "is_custom_tip_enabled"?: boolean; "is_smart_tips_enabled"?: boolean; /** minItems: 3. maxItems: 3. */ "smart_tip_money_options"?: Array<({ /** Use an exact numeric string, not a floating-point number. Format: int64. minimum: 1. */ "amount"?: string; }) & ({ /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; })>; /** minItems: 3. maxItems: 3. */ "tip_percentages"?: Array<number>; };
